const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={view:'workbench',mode:'sg',group:null,k:[0,0,0],doubleValued:false,bzType:'',labelK:null,tab:'characters',result:null,resultGroup:null,busy:false,calculationTicket:0,calculationRequest:null,calculationPromise:null,dbMode:'sg',dbQuery:'',dbPage:0,dbType:'all',angle:.48,tilt:.42,bandText:'',bandRevision:0,bandTicket:0,bandBusy:false};
let databases={},toastTimer;
const labels={workbench:['对称性工作台','从空间群到磁空间群，探索晶体的对称性与不可约表示。'],database:['群数据库','检索空间群、磁空间群与磁点群，查看原始对称操作。'],products:['直积分解','解析两个 k 星的表示张量积，追踪输出波矢与不可约分量。'],bands:['能带特征标匹配','读取本地 trace 文件，或输入已按当前操作排序的能带特征标。'],docs:['方法与使用说明','坐标约定、数值验证、数据来源与当前版本的功能范围。']};
labels.magnetictb=['磁性紧束缚模型','用晶体对称性约束跃迁参数，计算能带、薄膜和拓扑量。'];
labels.advanced=['精确代数与高维群','整数类与仿射类、算术中心化子、符号表示与 Hamiltonian，全部由 Python 在浏览器计算。'];
labels.crystkit=['晶体群工具','精确仿射运算、生成元、点轨道与空间群识别。'];
labels.pointgroups=['32 点群课堂','从对称操作到特征标与选择定则，边学、边看、边计算。'];
labels.academy=['空间群 · 双群 · 磁群课堂','从晶格平移到自旋与时间反演，结合交互实验学习晶体对称性。'];
labels.structure=['结构 → BC 晶胞','导入 POSCAR / CIF，识别空间群，转换基矢、原点与波矢。'];
const lattices={TricPrim:'三斜 · P',MonoPrim:'单斜 · P',MonoBase:'单斜 · C',OrthPrim:'正交 · P',OrthBase:'正交 · C',OrthBody:'正交 · I',OrthFace:'正交 · F',TetrPrim:'四方 · P',TetrBody:'四方 · I',TrigPrim:'三方 · R',HexaPrim:'六方 · P',CubiPrim:'立方 · P',CubiFace:'立方 · F',CubiBody:'立方 · I'};
const gid=(g=state.group,mode=state.mode)=>mode==='sg'?String(g.number):g.id;
const gtitle=(g=state.group)=>g.bcSymbol||g.symbol;
const list=mode=>mode==='sg'?databases.sg.groups:mode==='msg'?databases.msg.groups:databases.mpg.points;
const complex=x=>Array.isArray(x)?{re:x[0],im:x[1]}:typeof x==='number'?{re:x,im:0}:x;
function formatComplex(input,digits=5){const z=complex(input),tol=.5*10**-digits;const num=x=>Math.abs(x)<tol?'0':Number(x.toFixed(digits)).toString();if(Math.abs(z.im)<tol)return num(z.re);const im=Math.abs(Math.abs(z.im)-1)<tol?'i':num(Math.abs(z.im))+'i';if(Math.abs(z.re)<tol)return(z.im<0?'−':'')+im;return num(z.re)+(z.im<0?' − ':' + ')+im;}
const cf=x=>{try{return formatComplex(complex(x),4)}catch{return JSON.stringify(x)}};
const norm=x=>Math.abs(x)<1e-8?0:Number(x.toFixed(6));
function fraction(n){if(!Number.isFinite(n))return '?';for(let d=1;d<=24;d++)if(Math.abs(n*d-Math.round(n*d))<1e-7)return d===1?String(Math.round(n)):Math.round(n*d)+'/'+d;return String(norm(n));}
function parseNumber(s){if(!/^\s*[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?(?:\s*\/\s*[+-]?(?:\d+\.?\d*|\.\d+))?\s*$/.test(s))throw new Error('坐标仅支持数字、小数或分数，例如 1/2。');const a=s.split('/').map(Number);const n=a.length===2?a[0]/a[1]:a[0];if(!Number.isFinite(n)||Math.abs(n)>100)throw new Error('坐标必须为 −100 到 100 之间的有限数值。');return n;}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200);}
function download(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function showError(message){const dest=$('#calculation-error');if(dest)dest.innerHTML=`<div class="notice error" role="alert">${esc(message)}</div>`;else toast(message);}
function setView(view){if(!Object.hasOwn(labels,view))return;state.view=view;history.replaceState(null,'','#'+view);$('#breadcrumb').textContent=labels[view][0];$('#page-title').innerHTML=esc(labels[view][0])+(view==='workbench'?'<span class="beta">浏览器版</span>':'');$('#page-subtitle').textContent=labels[view][1];$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===view));render();}
function resultMatches(){return state.result&&gid()===gid(state.resultGroup,state.resultMode)&&state.mode===state.resultMode&&state.doubleValued===state.result.doubleValued&&state.k.every((x,i)=>Math.abs(x-state.result.k[i])<1e-8);}
function modeButtons(mode,attr='mode'){return `<div class="segment">${[['sg','空间群 SG'],['msg','磁空间群 MSG'],['mpg','磁点群 MPG']].map(([m,t])=>`<button data-${attr}="${m}" class="${m===mode?'active':''}">${t}</button>`).join('')}</div>`;}
function selectGroup(g,mode=state.mode){state.group=g;state.mode=mode;state.bzType='';state.labelK=null;state.k=[0,0,0];state.result=null;state.tab='characters';render();}
function render(){if(!state.group)return;$('#app').dataset.researchView=state.view;if(state.view==='workbench')renderWorkbench();else if(state.view==='database')renderDatabase();else if(state.view==='docs')renderDocs();else if(state.view==='academy')renderSymmetryCourseView({container:$('#app'),run:runPythonTask,toast,download,openGroup:({mode='sg',id,k=[0,0,0],doubleValued=false})=>{if(!['sg','msg','mpg'].includes(mode))return;const group=list(mode).find(g=>gid(g,mode)===String(id));if(!group){toast('未找到该群。');return;}state.group=group;state.mode=mode;state.k=mode==='mpg'?[0,0,0]:k;state.doubleValued=Boolean(doubleValued);state.bzType='';state.labelK=state.k.every(x=>x===0)?'Γ':null;state.result=null;state.tab='characters';setView('workbench');calculate();}});else if(state.view==='pointgroups')renderPointgroupView({container:$('#app'),toast,download,openGroup:number=>{const group=databases.sg.groups.find(g=>g.number===number);if(!group)return;state.group=group;state.mode='sg';state.k=[0,0,0];state.doubleValued=false;state.bzType='';state.labelK='Γ';state.result=null;state.tab='characters';setView('workbench');calculate();}});else if(state.view==='products')renderProducts();else if(state.view==='bands')renderBands();else if(state.view==='structure')renderStructureView({container:$('#app'),run:runPythonTask,toast,download,openGroup:(number,k,bzType)=>{state.group=databases.sg.groups.find(g=>g.number===number);state.mode='sg';state.bzType=bzType||'';state.labelK=null;state.k=k;state.result=null;state.tab='characters';setView('workbench');calculate();}});else if(state.view==='advanced')renderAdvancedView({container:$('#app'),run:runPythonTask,toast,download,sendToBands:payload=>{setResearchInput('magnetictb',payload);setView('magnetictb');toast('已载入精确模型的数值代入，可调整 k 路径后计算。');}});else if(['magnetictb','crystkit'].includes(state.view))renderResearchView(state.view,{container:$('#app'),run:runPythonTask,toast,download,context:{group:state.group,mode:state.mode,k:state.k,doubleValued:state.doubleValued}});}
function renderWorkbench(){const g=state.group;const current=resultMatches();const r=current?state.result:null;$('#app').innerHTML=`<div class="workspace-grid"><section class="panel"><div class="panel-top"><div class="panel-title"><span class="step">01</span> 定义对称性</div><span class="subtle">PARAMETERS</span></div><div class="panel-body">${modeButtons(state.mode)}
 <label class="field-label" for="group-search">${state.mode==='sg'?'空间群编号或符号':state.mode==='msg'?'磁空间群 · BNS / OG 编号':'磁点群编号或符号'}<span>${state.mode==='sg'?'1 — 230':state.mode==='msg'?'1,651 MAGNETIC GROUPS':'122 MAGNETIC POINT GROUPS'}</span></label>
 <div class="search-wrap"><div class="group-input"><input id="group-search" autocomplete="off" aria-label="搜索并选择群" value="${esc(gid(g))}   ${esc(gtitle(g))}"><span>⌕</span></div><div id="group-options" class="search-list hidden"></div></div>
 <div class="group-info"><strong>${esc(gtitle(g))}</strong><span class="tag">${esc(lattices[g.lattice]||g.lattice)}</span><span class="tag">${state.mode==='sg'?esc(g.pointGroup):'Type '+['','I','II','III','IV'][g.type]}</span>${g.ogId?`<span class="tag">OG ${g.ogId}</span>`:''}</div>
 <div class="field-label">波矢 k<span>BC 原胞倒易分数坐标</span></div><div class="coords">${state.k.map((v,i)=>`<div class="coord"><label for="k-${i}">k<sub>${['x','y','z'][i]}</sub></label><input id="k-${i}" aria-label="k ${['x','y','z'][i]}" value="${esc(v)}" ${state.mode==='mpg'?'disabled':''}></div>`).join('')}</div>
 <div class="presets">${(g.kpoints||[{label:'Γ',coordinates:[0,0,0]}]).slice(0,10).map((p,i)=>`<button data-preset="${i}" title="${esc((p.bzTypes||[]).join(', '))}: (${p.coordinates.map(fraction).join(', ')})" class="${p.coordinates.every((x,j)=>Math.abs(x-state.k[j])<1e-8)?'active':''}">${esc(p.label)}</button>`).join('')}<button id="generic-k" ${state.mode==='mpg'?'disabled':''}>一般 k</button></div>
 ${state.mode==='sg'&&(g.bzTypes||[]).length>1?`<label class="field-label" for="label-bz">标准标签的 BZ 类型</label><select class="form-select" id="label-bz"><option value="">全部类型 · 保留歧义</option>${g.bzTypes.map(type=>`<option value="${esc(type)}" ${state.bzType===type?'selected':''}>${esc(type)}</option>`).join('')}</select>`:''}<div class="spin-row"><div class="field-label">表示类型<small>单值 / 自旋双值</small></div><div class="segment"><button data-spin="false" class="${!state.doubleValued?'active':''}">单值 · 无 SOC</button><button data-spin="true" class="${state.doubleValued?'active':''}">双值 · SOC</button></div></div>
 <button id="calculate" class="primary" ${state.busy?'disabled':''}><span>${state.busy?'<i class="spinner"></i>正在计算…':'计算不可约表示'}</span><span>→</span></button>
 <p class="form-note">坐标按 BC 约定。SG 结果自动比对 BC / Bilbao 标准特征标；D₁、D₂… 保留为本次计算编号。</p><div id="calculation-error"></div></div></section>
 <section class="panel"><div class="panel-top"><div class="panel-title"><span class="step">02</span> 倒易空间</div><span class="subtle">k-STAR EXPLORER</span></div><div class="visual-body"><span class="viz-tag">${esc(g.lattice)} / RECIPROCAL CELL</span><svg id="reciprocal-viz" viewBox="0 0 430 303" role="img" aria-label="倒易原胞与 k 星交互示意图"></svg><span class="viz-caption">拖动旋转 · 示意晶格参数</span></div><div class="viz-legend"><span><i></i>选定 k 点</span><span><i class="ring"></i>等价星臂</span><span>虚线 / 倒易基矢</span></div><div class="viz-note"><span>k = (${state.k.map(fraction).join(', ')})</span><span>${r?r.star.length+' 个星臂':'运行计算以显示 k 星'}</span></div></section></div>
 <div class="stats"><div class="stat"><div class="stat-label">小群操作数<small>LITTLE GROUP ORDER</small></div><strong>${r?r.littleGroup.operations.length:'—'}</strong></div><div class="stat"><div class="stat-label">k 星臂数<small>ARMS OF THE k-STAR</small></div><strong>${r?r.star.length:'—'}</strong></div><div class="stat"><div class="stat-label">${r?.littleGroup.antiunitaryIndices.length?'不可约共表示':'不可约表示'}<small>${r?.littleGroup.antiunitaryIndices.length?'IRREDUCIBLE COREPS':'IRREDUCIBLE REPS'}</small></div><strong>${r?(r.littleGroup.antiunitaryIndices.length?r.corepresentations.length:r.irreps.length):'—'}</strong></div></div>
 <section class="panel results"><div class="result-header"><div class="result-heading">计算结果<small>${r?`${esc(gtitle(g))} · k = (${state.k.map(fraction).join(', ')})`:'选择群与波矢后开始计算'}</small></div><div class="result-tools"><button class="text-button" id="export-csv">↓ CSV</button><button class="text-button" id="export-json">↓ JSON</button></div></div><div class="tabs">${[['characters','特征标表'],['labels','BC / Bilbao 标签'],['operations','对称操作'],['matrices','表示矩阵'],['stars','k 星'],['coreps','磁共表示'],['full','全空间群表示']].map(([t,n])=>`<button data-tab="${t}" class="${state.tab===t?'active':''}">${n}</button>`).join('')}</div><div class="result-content" id="result-content"></div></section>`;
 bindWorkbench();if(state.busy){$$('#app input,#app #label-bz,#app [data-mode],#app [data-spin],#app .presets button').forEach(e=>e.disabled=true);}renderResults();renderViz();}
function bindWorkbench(){const input=$('#group-search');input.addEventListener('focus',()=>{input.select();showSearch('');});input.addEventListener('input',()=>showSearch(input.value));input.addEventListener('keydown',e=>{if(e.key==='Escape')$('#group-options').classList.add('hidden');if(e.key==='Enter'){e.preventDefault();$('#group-options button')?.click();}});$$('[data-mode]').forEach(b=>b.onclick=()=>selectGroup(list(b.dataset.mode)[b.dataset.mode==='sg'?224:b.dataset.mode==='msg'?1:1],b.dataset.mode));$$('[data-spin]').forEach(b=>b.onclick=()=>{try{readCoords();state.doubleValued=b.dataset.spin==='true';render();}catch(e){showError(e.message);}});$$('[data-preset]').forEach(b=>b.onclick=()=>{const point=(state.group.kpoints||[{coordinates:[0,0,0]}])[+b.dataset.preset];state.k=point.coordinates.slice();state.labelK=point.label;state.result=null;render();});$('#generic-k').onclick=()=>{state.k=[.123,.234,.345];state.labelK=null;state.result=null;render();};$$('.coords input').forEach(i=>i.onchange=()=>{try{readCoords();state.labelK=null;render();}catch(e){showError(e.message);}});if($('#label-bz'))$('#label-bz').onchange=e=>{state.bzType=e.target.value;state.result=null;render();};$('#calculate').onclick=()=>calculate();$$('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));renderResults();});$('#export-json').onclick=exportJSON;$('#export-csv').onclick=exportCSV;}
function showSearch(q){q=q.trim().toLowerCase().replace(/\s/g,'');const rows=list(state.mode).filter(g=>[gid(g),g.symbol,g.bcSymbol,g.ogId].some(v=>String(v||'').toLowerCase().replace(/\s/g,'').includes(q))).slice(0,70);const el=$('#group-options');el.classList.remove('hidden');el.innerHTML=rows.length?rows.map(g=>`<button data-select="${esc(gid(g))}"><span>${esc(gid(g))} <b>${esc(gtitle(g))}</b></span><small>${esc(lattices[g.lattice]||'')}${g.type?' · '+['','I','II','III','IV'][g.type]:''}</small></button>`).join(''):'<div class="empty-state">未找到匹配的编号或符号</div>';$$('button',el).forEach(b=>b.onclick=()=>selectGroup(list(state.mode).find(g=>gid(g)===b.dataset.select)));}
function readCoords(){if(state.view==='workbench'&&$('#k-0')){const k=[0,1,2].map(i=>parseNumber($('#k-'+i).value));if(k.some((x,i)=>Math.abs(x-state.k[i])>1e-8))state.labelK=null;state.k=k;}}
function compute(payload,action='analyze'){return runPythonTask(action,payload);}
async function calculate(){
 try{
  if(state.view==='workbench'&&$('#group-search')){const raw=$('#group-search').value.trim();if(raw!==(gid()+'   '+gtitle())){const exact=list(state.mode).filter(g=>[gid(g),g.symbol,g.bcSymbol,g.ogId].some(v=>String(v||'').toLowerCase()===raw.toLowerCase()));if(exact.length!==1)throw new Error('请从搜索列表选择唯一的群，或输入完整编号。');if(state.group!==exact[0]){state.bzType='';state.labelK=null;}state.group=exact[0];}}
  readCoords();const group=state.group,mode=state.mode,k=state.k.slice(),doubleValued=state.doubleValued,bzType=state.bzType,labelK=state.labelK;
  const same=request=>request&&request.group===group&&request.mode===mode&&request.doubleValued===doubleValued&&request.bzType===bzType&&request.labelK===labelK&&request.k.every((x,i)=>Math.abs(x-k[i])<1e-8);
  if(state.busy&&same(state.calculationRequest))return state.calculationPromise;
  // Replacing a symmetry request cancels only that request, never another tool.
  if(state.busy&&state.calculationRequest)cancelPython();
  const ticket=++state.calculationTicket;
  state.calculationRequest={group,mode,k,doubleValued,bzType,labelK};state.busy=true;
  const contextMatches=()=>state.group===group&&state.mode===mode&&state.doubleValued===doubleValued&&state.bzType===bzType&&state.labelK===labelK&&state.k.every((x,i)=>Math.abs(x-k[i])<1e-8);
  const showHere=()=>['workbench','bands'].includes(state.view)&&contextMatches();
  if(showHere())render();
  const pending=(async()=>{
   try{
    const result=await compute({operations:group.operations,k,basis:group.basis,doubleValued,...(mode==='sg'?{group_number:group.number,...(bzType?{bz_type:bzType}:{}),...(labelK?{k_label:labelK}:{})}:{})});
    if(ticket!==state.calculationTicket)return false;
    state.busy=false;
    if(!contextMatches())return false;
    state.result=result;state.resultGroup=group;state.resultMode=mode;
    if(showHere()){render();toast('计算完成 · 数值一致性检查已通过');}
    return true;
   }catch(e){
    if(ticket!==state.calculationTicket)return false;
    state.busy=false;if(showHere())render();
    if(contextMatches())showError(e.message);
    return false;
   }finally{if(ticket===state.calculationTicket){state.busy=false;state.calculationRequest=null;state.calculationPromise=null;}}
  })();
  state.calculationPromise=pending;return pending;
 }catch(e){showError(e.message);return false;}
}
function matrixHTML(m){return `<div class="matrix" style="grid-template-columns:repeat(${m[0]?.length||1},auto)">${m.flat().map(x=>`<span>${typeof x==='number'?fraction(x):esc(cf(x))}</span>`).join('')}</div>`;}
function tableHTML(headers,rows,cls=''){return `<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
const labelStatus=status=>({matched:'已匹配',ambiguous:'多个候选',unmatched:'未匹配'}[status]||status||'—');
function labelEntry(result,id){return result.standardLabels?.mappings?.find(m=>m.local_label===id);}
function labelDisplay(result,id){const m=labelEntry(result,id);return [id,m?.bc_label?'BC '+m.bc_label:null,m?.bilbao_label?'Bilbao '+m.bilbao_label:null].filter(Boolean).join(' · ');}
function standardLabelSummary(result){const info=result.standardLabels;if(!info)return '当前磁群结果保留本地编号；普通空间群标签不能直接套用于磁共表示。';const rows=info.mappings||[];return `标准标签：BC ${rows.filter(m=>m.bc_label).length} / ${result.irreps.length}，Bilbao ${rows.filter(m=>m.bilbao_label).length} / ${result.irreps.length}。空项与候选原因见“BC / Bilbao 标签”。`;}
function renderStandardLabels(el,r){
 const info=r.standardLabels;
 if(!info){el.innerHTML='<div class="notice">本入口匹配普通空间群的 BC / Bilbao 小群表示。磁共表示仍使用本地 C 编号；需要结合磁群的独立标准表命名。</div>';return;}
 const rows=info.mappings||[];
 el.innerHTML=`<p class="mini-heading">${esc(standardLabelSummary(r))}</p>${tableHTML(['本地编号','BC 标准标签','Bilbao 标准标签','匹配状态'],rows.map(m=>[esc(m.local_label),esc(m.bc_label||'—'),esc(m.bilbao_label||'—'),esc('BC: '+labelStatus(m.bc_status||m.status)+' / Bilbao: '+labelStatus(m.bilbao_status))]))}<div class="notice" style="margin-top:18px">标签通过完整特征标向量、操作顺序与平移 / 自旋相位比对。不同约定下不能仅按表示维数或编号对应。标准表没有覆盖、波矢存在歧义或无法唯一匹配时保留候选，不自动指定名称。</div>${info.message?`<p class="form-note">${esc(info.message)}</p>`:''}<p class="form-note"><a href="docs/standard-labels.md" target="_blank">标签来源、匹配算法与适用范围 ↗</a></p><details class="structure-details"><summary>查看映射证书与未匹配候选</summary><pre class="structure-json">${esc(JSON.stringify(info,null,2))}</pre></details>`;
}
function renderResults(){const el=$('#result-content');if(!el)return;const r=resultMatches()?state.result:null;if(!r){el.innerHTML=`<div class="empty-state">${state.busy?'<span class="spinner"></span>正在浏览器中构造并验证表示矩阵…':'参数已就绪。点击“计算不可约表示”生成结果。'}</div>`;return;}
 if(state.tab==='characters'){el.innerHTML=`<p class="mini-heading">${r.littleGroup.antiunitaryIndices.length?'幺正子群不可约表示的特征标 · 共表示请查看“磁共表示”':'小群不可约表示 · 每列对应一个操作'}</p>${tableHTML(['本地编号','BC 标签','Bilbao 标签','维数',...r.littleGroup.unitaryOperations.map((o,i)=>`<span title="操作 ${i+1}">${esc(o.name||'g'+(i+1))}</span>`)],r.irreps.map(ir=>[esc(ir.label),esc(labelEntry(r,ir.label)?.bc_label||'—'),esc(labelEntry(r,ir.label)?.bilbao_label||'—'),ir.dimension,...ir.characters.map(x=>esc(cf(x)))]))}<div class="note-strip"><span>χ(g) = Tr D(g) · 列序与“表示矩阵”和 JSON 导出一致。</span><span class="badge">✓ 正交性与乘法关系验证</span></div><div class="note-strip"><span>${esc(standardLabelSummary(r))}</span><span>Σ dᵢ² = ${r.irreps.reduce((s,x)=>s+x.dimension*x.dimension,0)} = |Hₖ|</span></div>`;}
 else if(state.tab==='labels'){renderStandardLabels(el,r);}
 else if(state.tab==='operations'){el.innerHTML=tableHTML(['#','操作','旋转 R','平移 t','类型'],r.littleGroup.operations.map((o,i)=>[i+1,esc(o.name||'g'+(i+1)),matrixHTML(o.rotation),'('+o.translation.map(fraction).join(', ')+')',o.antiunitary?'<span class="type-dot">反幺正 · T</span>':'幺正']),'operation-table')+'<div class="note-strip">Seitz 操作 {R | t}。表中为模平移子群的代表元；自旋双值使用因子系统，未重复显示带横线的元素。</div>';}
 else if(state.tab==='stars'){el.innerHTML=tableHTML(['星臂','kₓ','kᵧ','k𝓏','生成操作数量'],r.star.map((s,i)=>[i+1,...s.k.map(fraction),s.operationIndices?.length??'—']))+'<div class="note-strip">按倒易整数向量取模。反幺正操作的波矢作用为 −R⁻ᵀk。</div>';}
 else if(state.tab==='matrices'){el.innerHTML=`<div class="controls-row"><label for="irrep-select">选择小群表示</label><select id="irrep-select">${r.irreps.map((ir,i)=>`<option value="${i}">${esc(labelDisplay(r,ir.label))} · ${ir.dimension} 维</option>`).join('')}</select><span class="subtle">矩阵基底由数值对角化选取</span></div><div id="matrix-list" class="matrix-grid"></div>`;const draw=()=>{const ir=r.irreps[+$('#irrep-select').value];$('#matrix-list').innerHTML=ir.matrices.map((m,i)=>`<div class="matrix-box"><div>${i+1} · ${esc(r.littleGroup.unitaryOperations[i]?.name||'g'+(i+1))}</div>${matrixHTML(m)}</div>`).join('');};$('#irrep-select').onchange=draw;draw();}
 else if(state.tab==='coreps'){renderCoreps(el,r);}
 else if(state.tab==='full'){renderFull(el,r);}
}
function renderCoreps(el,r){if(!r.littleGroup.antiunitaryIndices.length){el.innerHTML='<div class="notice">当前小群没有反幺正操作，其表示就是普通不可约表示。可以选择磁空间群或磁点群，并使用 Γ 点查看共表示。</div>';return;}el.innerHTML=tableHTML(['共表示','Wigner 类型','维数','关联小群表示'],r.corepresentations.map((c,i)=>[esc(c.label||'C'+(i+1)),esc(c.type||c.wignerType),c.dimension,esc(c.type==='a'?c.unitaryIrrep:c.type==='b'?'2 × '+c.unitaryIrrep:c.unitaryIrrep+' + '+c.partnerIrrep)]))+'<div class="notice" style="margin-top:16px">反幺正操作表示为 A·K，其中 K 为复共轭。类型 a、b、c 由反幺正陪集的 Wigner 判据确定；双值计算包含 T² = −1。</div><div id="corep-matrices"></div>';const target=$('#corep-matrices');if(r.corepresentations.some(c=>c.matrices)){target.innerHTML=`<div class="controls-row" style="margin-top:18px"><label for="corep-select">查看共表示矩阵</label><select id="corep-select">${r.corepresentations.map((c,i)=>`<option value="${i}">${esc(c.label||'C'+(i+1))} · ${c.dimension} 维</option>`).join('')}</select></div><div class="matrix-grid" id="corep-matrix-list"></div>`;const draw=()=>{const c=r.corepresentations[+$('#corep-select').value];$('#corep-matrix-list').innerHTML=(c.matrices||[]).map((m,i)=>`<div class="matrix-box"><div>${esc(r.littleGroup.operations[i]?.name||'g'+(i+1))}${r.littleGroup.operations[i]?.antiunitary?' · K':''}</div>${matrixHTML(m)}</div>`).join('');};$('#corep-select').onchange=draw;draw();}}
async function renderFull(el,r){
 const reps=r.corepresentations.length?r.corepresentations:r.irreps;
 el.innerHTML=`<div class="controls-row"><label for="full-irrep">诱导自小群${r.corepresentations.length?'共':''}表示</label><select id="full-irrep">${reps.map((ir,i)=>`<option value="${i}">${esc(labelDisplay(r,ir.label))} · ${ir.dimension} 维</option>`).join('')}</select><button class="secondary small" id="induce">生成全空间群表示</button></div><div class="notice">全表示维数 = 小群表示维数 × k 星臂数。反幺正操作的矩阵必须与复共轭 K 一起使用。</div><div id="induction-output"></div>`;
 $('#full-irrep').onchange=()=>{state.full=null;$('#induction-output').innerHTML='';};
 $('#induce').onclick=async()=>{const b=$('#induce'),selector=$('#full-irrep'),destination=$('#induction-output'),selected=+selector.value;const current=()=>state.result===r&&resultMatches()&&$('#induction-output')===destination&&selector.isConnected&&+selector.value===selected;b.disabled=true;selector.disabled=true;try{const group=state.resultGroup;const full=await compute({group,k:r.k,analysis:r,irrepIndex:selected,doubleValued:r.doubleValued},'induce');if(!current())return;state.full=full;const output=$('#induction-output');if(!output)return;output.innerHTML=`<div class="controls-row" style="margin-top:20px"><span class="mini-heading">${esc(full.id)} · ${full.dimension} 维 · ${full.star.length} 个星臂</span><button class="text-button" id="export-full">↓ 完整矩阵 JSON</button></div><div class="controls-row"><label for="full-operation">对称操作</label><select id="full-operation">${group.operations.map((o,i)=>`<option value="${i}">${i+1} · ${esc(o.name)}${o.antiunitary?' · K':''}</option>`).join('')}</select></div><div class="table-wrap" style="padding:20px;max-height:420px" id="full-matrix"></div><p class="form-note" id="full-matrix-caption"></p><span class="badge">✓ 诱导表示乘法与平移相位检查通过</span>`;const draw=()=>{const i=+$('#full-operation').value;$('#full-matrix').innerHTML=matrixHTML(full.matrices[i]);$('#full-matrix-caption').textContent=group.operations[i].antiunitary?'此矩阵表示 U·K。反幺正矩阵的迹不是不依赖基底的特征标。':'特征标 χ = '+cf(full.characters[i]);};$('#full-operation').onchange=draw;$('#export-full').onclick=()=>download(JSON.stringify(full,null,2),'full-representation.json');draw();}catch(e){if(current())destination.innerHTML=`<div class="notice error" style="margin-top:16px">${esc(e.message)}</div>`;}finally{if(b.isConnected)b.disabled=false;if(selector.isConnected)selector.disabled=false;}};
}
function exportJSON(){if(!resultMatches()){toast('请先运行一次计算');return;}download(JSON.stringify({application:'Symmetry Lab',version:'0.1.0',group:{mode:state.resultMode,id:gid(state.resultGroup,state.resultMode),symbol:gtitle(state.resultGroup)},sources:['https://github.com/goodluck1982/SpaceGroupIrep','https://github.com/goodluck1982/MSGCorep'],notice:'D/C labels are local IDs. Certified standard label correspondence and unresolved candidates, when available, are recorded separately in standardLabels.',...state.result},null,2),`symmetry-${gid(state.resultGroup,state.resultMode)}.json`);}
function exportCSV(){if(!resultMatches()){toast('请先运行一次计算');return;}const r=state.result;const rows=[['irrep','BC','Bilbao','dimension',...r.littleGroup.unitaryOperations.map((o,i)=>o.name||'g'+i)],...r.irreps.map(ir=>[ir.label,labelEntry(r,ir.label)?.bc_label||'',labelEntry(r,ir.label)?.bilbao_label||'',ir.dimension,...ir.characters.map(cf)])];download('\uFEFF'+rows.map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n'),'characters.csv','text/csv;charset=utf-8');}

function renderViz(){const svg=$('#reciprocal-viz');if(!svg)return;const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];const dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0);const basis=state.group.basis||[[1,0,0],[0,1,0],[0,0,1]],vol=dot(basis[0],cross(basis[1],basis[2]));const recip=[cross(basis[1],basis[2]),cross(basis[2],basis[0]),cross(basis[0],basis[1])].map(v=>v.map(x=>x/vol));const tocart=k=>[0,1,2].map(i=>k.reduce((s,x,j)=>s+x*recip[j][i],0));const scale=96/Math.max(...recip.map(v=>Math.hypot(...v)));const proj=k=>{const [x,y,z]=tocart(k),a=state.angle,b=state.tilt;const x1=x*Math.cos(a)-y*Math.sin(a),y1=x*Math.sin(a)+y*Math.cos(a);return [215+x1*scale,150+(y1*Math.sin(b)-z*Math.cos(b))*scale];};const draw=()=>{const vertices=[];for(let x of [-.5,.5])for(let y of [-.5,.5])for(let z of [-.5,.5])vertices.push([x,y,z]);let paths='';for(let i=0;i<8;i++)for(let j=i+1;j<8;j++)if(vertices[i].filter((v,d)=>v!==vertices[j][d]).length===1){const a=proj(vertices[i]),b=proj(vertices[j]);paths+=`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#a6bfad" stroke-width="1.2"/>`;}
 const center=proj([0,0,0]);let axes='';for(let i=0;i<3;i++){const k=[0,0,0];k[i]=.9;const p=proj(k);axes+=`<line x1="${center[0]}" y1="${center[1]}" x2="${p[0]}" y2="${p[1]}" stroke="#bacdc0" stroke-dasharray="3 4"/><text x="${p[0]+6}" y="${p[1]-5}" fill="#809e89" font-size="13" font-family="monospace">b${['₁','₂','₃'][i]}</text>`;}
 const points=resultMatches()?state.result.star.map(s=>s.k.map(x=>x-Math.floor(x+.5))):[state.k];const dots=points.map((k,i)=>{const p=proj(k);return `<circle cx="${p[0]}" cy="${p[1]}" r="${i===0?4:3}" fill="${i===0?'#23785f':'#edf5ec'}" stroke="#23785f" stroke-width="1.3"/>${i===0?`<circle cx="${p[0]}" cy="${p[1]}" r="9" fill="#23785f10"/><text x="${p[0]+11}" y="${p[1]-8}" fill="#286d4d" font-size="16" font-family="serif">${state.k.every(v=>v===0)?'Γ':'k'}</text>`:''}`;}).join('');svg.innerHTML=`<defs><pattern id="grid" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#dce8df"/></pattern></defs><rect width="430" height="303" fill="url(#grid)" opacity=".5"/>${axes}${paths}${dots}`;};draw();let drag=null;svg.onpointerdown=e=>{drag=[e.clientX,e.clientY];svg.setPointerCapture(e.pointerId);svg.style.cursor='grabbing';};svg.onpointermove=e=>{if(!drag)return;state.angle+=(e.clientX-drag[0])*.009;state.tilt=Math.max(-1.3,Math.min(1.3,state.tilt+(e.clientY-drag[1])*.009));drag=[e.clientX,e.clientY];draw();};svg.onpointerup=()=>{drag=null;svg.style.cursor='grab';};}

function renderDatabase(){const groups=list(state.dbMode);const q=state.dbQuery.trim().toLowerCase();const filtered=groups.filter(g=>(state.dbType==='all'||String(g.type)===state.dbType)&&[gid(g,state.dbMode),g.symbol,g.bcSymbol,g.ogId,g.lattice,g.pointGroup].some(v=>String(v||'').toLowerCase().includes(q)));const pageSize=25;state.dbPage=Math.min(state.dbPage,Math.max(0,Math.ceil(filtered.length/pageSize)-1));const selected=filtered.slice(state.dbPage*pageSize,(state.dbPage+1)*pageSize);$('#app').innerHTML=`<section class="panel"><div class="panel-body">${modeButtons(state.dbMode,'db-mode')}<div class="controls-row" style="margin-top:20px"><input id="db-search" placeholder="搜索编号、国际符号、OG 编号或晶格…" aria-label="搜索数据库" value="${esc(state.dbQuery)}">${state.dbMode==='sg'?'':`<select id="db-type" aria-label="磁群类型"><option value="all">全部类型</option>${[1,2,3,4].map(t=>`<option value="${t}" ${String(t)===state.dbType?'selected':''}>Type ${['','I','II','III','IV'][t]}</option>`).join('')}</select>`}<span class="subtle">${filtered.length} 个匹配结果</span></div>${tableHTML([state.dbMode==='sg'?'No.':state.dbMode==='msg'?'BNS':'MPG','国际符号 / BC','晶格',state.dbMode==='msg'?'OG 编号':'点群 / 类型','操作数',''],selected.map(g=>[esc(gid(g,state.dbMode)),`<span class="db-symbol">${esc(gtitle(g))}</span>`,esc(lattices[g.lattice]||g.lattice),esc(state.dbMode==='msg'?g.ogId:g.pointGroup||['','I','II','III','IV'][g.type]),g.operations.length,`<button class="text-button" data-open-group="${esc(gid(g,state.dbMode))}">打开工作台 ↗</button>`]))}<div class="pagination"><span>第 ${state.dbPage+1} / ${Math.max(1,Math.ceil(filtered.length/pageSize))} 页 · 数据来自上游完整表</span><div><button class="secondary small" id="prev-page" ${state.dbPage===0?'disabled':''}>← 上一页</button><button class="secondary small" id="next-page" ${(state.dbPage+1)*pageSize>=filtered.length?'disabled':''}>下一页 →</button></div></div></div></section>`;$$('[data-db-mode]').forEach(b=>b.onclick=()=>{state.dbMode=b.dataset.dbMode;state.dbPage=0;state.dbType='all';state.dbQuery='';renderDatabase();});$('#db-search').oninput=e=>{const pos=e.target.selectionStart;state.dbQuery=e.target.value;state.dbPage=0;renderDatabase();$('#db-search').focus();$('#db-search').setSelectionRange(pos,pos);};if($('#db-type'))$('#db-type').onchange=e=>{state.dbType=e.target.value;state.dbPage=0;renderDatabase();};$('#prev-page').onclick=()=>{state.dbPage--;renderDatabase();};$('#next-page').onclick=()=>{state.dbPage++;renderDatabase();};$$('[data-open-group]').forEach(b=>b.onclick=()=>{state.group=groups.find(g=>gid(g,state.dbMode)===b.dataset.openGroup);state.mode=state.dbMode;state.result=null;state.k=[0,0,0];setView('workbench');calculate();});}

function activeContext(){return `<div class="notice">当前选择：<b>${esc(gtitle())}</b> (${state.mode.toUpperCase()} ${esc(gid())})，k = (${state.k.map(fraction).join(', ')})，${state.doubleValued?'双值':'单值'}。<button class="text-button" data-return-workbench>更改参数 ↗</button></div>`;}
function renderProducts(){
 const group=state.group;const ticket=state.productTicket=(state.productTicket||0)+1;const current=()=>state.view==='products'&&state.productTicket===ticket&&state.group===group;const pf=state.productForm??={k1:state.k.slice(),k2:state.k.slice(),double1:state.doubleValued,double2:state.doubleValued};if(state.mode==='mpg'){pf.k1=[0,0,0];pf.k2=[0,0,0];}
 $('#app').innerHTML=`${activeContext()}<section class="panel" style="margin-top:20px"><div class="panel-top"><div class="panel-title">定义两个 k 星</div><span class="subtle">FULL STAR TENSOR PRODUCT</span></div><div class="panel-body"><div class="workspace-grid">${[1,2].map(n=>`<div><div class="field-label">因子 ${n} · k${n}<span>BC 原胞倒易分数坐标</span></div><div class="coords">${pf['k'+n].map((v,i)=>`<div class="coord"><label for="p${n}-${i}">${['x','y','z'][i]}</label><input id="p${n}-${i}" value="${fraction(v)}" aria-label="因子 ${n} k ${i}" ${state.mode==='mpg'?'disabled':''}></div>`).join('')}</div><div class="inline-row"><label for="pspin-${n}" class="subtle">自旋类型</label><select id="pspin-${n}" class="form-select"><option value="false" ${!pf['double'+n]?'selected':''}>单值</option><option value="true" ${pf['double'+n]?'selected':''}>双值 · SOC</option></select></div></div>`).join('')}</div><button class="primary" id="product-prepare" style="margin-top:12px">计算可选表示 →</button><div id="product-error"></div><div id="product-selection"></div></div></section><section class="panel" style="margin-top:20px"><div class="panel-top"><div class="panel-title">直积分解结果</div><span class="subtle">MOMENTUM SECTORS</span></div><div id="product-output" class="panel-body"><div class="empty-state">选择波矢和自旋类型，再选择两个不可约表示。</div></div></section>`;bindReturn();
 $('#product-prepare').onclick=async()=>{try{pf.k1=[0,1,2].map(i=>parseNumber($('#p1-'+i).value));pf.k2=[0,1,2].map(i=>parseNumber($('#p2-'+i).value));pf.double1=$('#pspin-1').value==='true';pf.double2=$('#pspin-2').value==='true';$('#product-prepare').disabled=true;$('#product-prepare').textContent='正在计算小群表示…';$('#product-error').innerHTML='';$$('#app .coords input,#app [id^="pspin-"]').forEach(i=>i.disabled=true);const params=structuredClone(pf);const a1=await compute({operations:group.operations,basis:group.basis,k:params.k1,doubleValued:params.double1});if(!current())return;const a2=await compute({operations:group.operations,basis:group.basis,k:params.k2,doubleValued:params.double2});if(!current())return;const reps=a=>a.corepresentations.length?a.corepresentations:a.irreps;const saved=JSON.stringify(pf);$('#product-selection').innerHTML=`<div class="product-grid" style="margin-top:20px">${[a1,a2].map((a,n)=>`${n?'<span>⊗</span>':''}<select class="form-select" id="product-${n}">${reps(a).map((r,i)=>`<option value="${i}">${esc(r.label)} · ${r.dimension} × ${a.star.length} = ${r.dimension*a.star.length} 维</option>`).join('')}</select>`).join('')}</div><button class="primary" id="product-run" style="margin-top:16px">分解全 k 星直积 →</button><p class="form-note">每个 D / C 标签只对应其所在波矢和自旋类型。计算自动将双值奇偶性和总波矢带入输出表示。</p>`;
 $('#product-run').onclick=async()=>{const button=$('#product-run');try{if(JSON.stringify(pf)!==saved)throw new Error('参数已变更，请重新计算可选表示。');button.disabled=true;$('#product-output').innerHTML='<div class="empty-state"><span class="spinner"></span>正在解析平移子空间并分解直积…</div>';$$('#app .coords input,#app [id^="pspin-"],#product-prepare,#product-0,#product-1').forEach(i=>i.disabled=true);const payload={group,k1:params.k1,k2:params.k2,analysis1:a1,analysis2:a2,irrepIndex1:+$('#product-0').value,irrepIndex2:+$('#product-1').value,double1:params.double1,double2:params.double2};const result=await compute(payload,'product');if(!current())return;state.productResult=result;$('#product-output').innerHTML=`<div class="notice">${esc(result.left.id)} (${result.left.dimension} 维) ⊗ ${esc(result.right.id)} (${result.right.dimension} 维) · 输出为${result.doubleValued?'双值':'单值'}表示 · 总维数 ${result.productDimension} = ${result.decomposedDimension}</div><div style="margin-top:18px">${tableHTML(['输出 k','星臂数','不可约分量','全表示维数','重数'],result.outputs.flatMap(o=>o.terms.map(t=>['('+o.k.map(fraction).join(', ')+')',o.star.length,esc(t.label||t.id),t.dimension,t.multiplicity])))}</div><div class="note-strip"><span>✓ 总维数守恒 · 平移本征空间与特征标重构通过</span><button class="text-button" id="export-product">↓ 完整结果 JSON</button></div>`;$('#export-product').onclick=()=>download(JSON.stringify(result,null,2),'star-product.json');}catch(e){if(!current())return;$('#product-error').innerHTML=`<div class="notice error" style="margin-top:14px">${esc(e.message)}</div>`;}finally{if(current()){$$('#app .coords input,#app [id^="pspin-"],#product-prepare,#product-0,#product-1').forEach(i=>i.disabled=state.mode==='mpg'&&i.tagName==='INPUT');button.disabled=false;}}};
 for(const input of $$('#app .coords input,#app [id^="pspin-"]'))input.addEventListener('change',()=>{$('#product-selection').innerHTML='';});
 }catch(e){if(!current())return;$('#product-error').innerHTML=`<div class="notice error" style="margin-top:14px">${esc(e.message)}</div>`;}finally{if(current()){$('#product-prepare').disabled=false;$('#product-prepare').textContent='计算可选表示 →';$$('#app .coords input,#app [id^="pspin-"]').forEach(i=>i.disabled=state.mode==='mpg'&&i.tagName==='INPUT');}}};
}
function decompositionText(terms){const data=Array.isArray(terms)?terms:terms.terms||terms.decomposition||terms.multiplicities||[];return data.filter(t=>(t.multiplicity??t.coefficient??t.count??0)>0).map(t=>`${(t.multiplicity??t.coefficient??t.count)>1?(t.multiplicity??t.coefficient??t.count)+' ':''}${t.label||t.irrep?.label||t.irrepId||t.id}`).join(' ⊕ ')||JSON.stringify(terms);}
function bindReturn(){$$('[data-return-workbench]').forEach(b=>b.onclick=()=>setView('workbench'));}

function renderBands(){const ticket=++state.bandTicket;const current=()=>state.view==='bands'&&state.bandTicket===ticket;const r=resultMatches()?state.result:null;$('#app').innerHTML=`${activeContext()}<div class="workspace-grid" style="margin-top:20px"><section class="panel"><div class="panel-top"><div class="panel-title">载入能带数据</div><span class="subtle">LOCAL FILE</span></div><div class="panel-body"><div class="controls-row"><label class="secondary small" for="trace-file">↑ 打开 trace.txt / JSON</label><input type="file" id="trace-file" class="sr-only" accept=".txt,.json,.dat"><button class="text-button" id="band-template">JSON 模板</button><button class="text-button" id="load-trace-example">载入真实示例</button></div><p class="form-note">trace 必须来自对应群的 BC 原胞与自旋框架。可先在“结构 → BC 晶胞”转换结构；已有 trace 的相位和自旋框架仍需单独核对。文件只在本机读取。</p><textarea class="band-input" id="band-data" aria-label="能带特征标 JSON 或 trace 内容" placeholder='{"bands":[{"index":1,"energy":-1.2,"characters":[1,1]}]}'>${esc(state.bandText)}</textarea><button class="primary" id="band-run" ${state.busy?'disabled':''}>解析并匹配表示 →</button><div id="band-error"></div></div></section><section class="panel"><div class="panel-top"><div class="panel-title">匹配结果</div><span class="subtle">CHARACTER MATCHING</span></div><div class="panel-body" id="band-output"><div class="empty-state">导入文件后显示能级、简并度与表示分解。<br>JSON 的特征标顺序须与当前幺正操作顺序一致。</div></div></section></div><div class="notice" style="margin-top:20px">匹配使用完整特征标向量，拒绝非整数或无法重构的分解。普通空间群可同时显示工作台已匹配的 BC / Bilbao 标签；磁共表示保留本地编号。</div>`;bindReturn();
 const input=$('#band-data'),fileInput=$('#trace-file'),runButton=$('#band-run'),exampleButton=$('#load-trace-example');
 const invalidate=()=>{$('#band-output').innerHTML='<div class="empty-state">输入已修改，请重新匹配表示。</div>';$('#band-error').innerHTML='';};
 input.oninput=e=>{state.bandRevision++;state.bandText=e.target.value;invalidate();};
 fileInput.onchange=async e=>{
  const file=e.target.files[0];if(!file)return;
  if(file.size>10*1024*1024){toast('文件超过 10 MiB，请使用较小的 k 点区间');return;}
  const revision=++state.bandRevision;runButton.disabled=true;
  try{const text=await file.text();if(!current()||state.bandRevision!==revision)return;state.bandRevision++;state.bandText=text;input.value=text;invalidate();toast('已载入 '+file.name);}
  catch(e){if(current())toast(e.message||'文件读取失败。');}
  finally{if(current())runButton.disabled=state.busy||state.bandBusy;}
 };
 $('#band-template').onclick=()=>{if(!r||!resultMatches()){toast('请先在工作台运行计算');return;}download(JSON.stringify({description:'填写真实能带特征标，按照 operations 列序。此模板不包含示例计算结果。',group:{id:gid(),mode:state.mode},k:state.k,doubleValued:state.doubleValued,operations:r.littleGroup.unitaryOperations,bands:[]},null,2),'band-template.json');};
 runButton.onclick=()=>runBands();
 exampleButton.onclick=async()=>{
  const revision=++state.bandRevision;exampleButton.disabled=true;runButton.disabled=true;
  try{
   const response=await fetch('examples/trace-msg.txt');if(!response.ok)throw new Error('真实示例读取失败。');
   const text=await response.text();if(!current()||state.bandRevision!==revision)return;
   const group=databases.msg.groups.find(g=>g.id==='166.101');
   state.bandText=text;state.mode='msg';state.group=group;state.k=[0,0,0];state.doubleValued=true;state.result=null;
   const succeeded=await calculate();
   if(succeeded&&state.view==='bands'&&state.group===group&&state.bandRevision===revision)await runBands();
  }catch(e){if(current())toast(e.message);}
  finally{if(exampleButton.isConnected)exampleButton.disabled=state.bandBusy;if(runButton.isConnected)runButton.disabled=state.busy||state.bandBusy;}
 };
 if(state.bandBusy)for(const control of [input,fileInput,runButton,exampleButton])control.disabled=true;
}
async function runBands(){
 if(state.bandBusy)return false;
 const out=$('#band-output'),err=$('#band-error'),button=$('#band-run'),input=$('#band-data');
 if(!out||!err||!button||!input)return false;
 const controls=[input,$('#trace-file'),$('#load-trace-example'),button];
 err.innerHTML='';
 try{
  const text=input.value.trim();if(!text)throw new Error('请选择文件或输入数据。');
  const r=resultMatches()?state.result:null;if(!r)throw new Error('请先在工作台计算对应群、k 点和自旋类型。');
  const group=state.group,mode=state.mode,revision=state.bandRevision,k=state.k.slice(),doubleValued=state.doubleValued;
  state.bandBusy=true;controls.forEach(control=>control.disabled=true);
  const response=await compute({group,analysis:r,text,k,doubleValued,mode},'match_bands');
  if(!out.isConnected||state.result!==r||state.bandRevision!==revision||input.value.trim()!==text||!resultMatches()||state.group!==group||state.mode!==mode)return false;
  const rows=response.bands;
  out.innerHTML=tableHTML(['能带','能量 / eV','表示分解'],rows.map(b=>[esc(b.index),typeof b.energy==='number'?b.energy.toFixed(6):'—',esc(decompositionText(b.terms.map(t=>({...t,label:labelDisplay(r,t.label||t.id)}))))]))+'<p class="form-note">已匹配 '+rows.length+' 个能级。Python 已检验特征标重构与简并度；保留本地编号并附上已匹配的标准标签。</p><button class="text-button" id="export-bands">↓ 导出能带匹配 JSON</button>';
  $('#export-bands').onclick=()=>download(JSON.stringify({group:{id:gid(group,mode),mode},k:r.k,doubleValued:r.doubleValued,standardLabels:r.standardLabels,bands:rows},null,2),'band-representations.json');
  return true;
 }catch(e){if(err.isConnected)err.innerHTML='<div class="notice error">'+esc(e.message)+'</div>';return false;}
 finally{
  state.bandBusy=false;
  if(out.isConnected){controls.forEach(control=>control.disabled=false);button.disabled=state.busy;}
  else if(state.view==='bands')renderBands();
 }
}

function renderDocs(){$('#app').innerHTML=`<div class="docs-layout"><section class="panel prose"><h2>对称性计算，在浏览器里完成</h2><p>本网站整合 SpaceGroupIrep、MSGCorep、MagneticTB 与 CrystKit 的数据和算法工作流。已实现的科学计算统一由 Python 在浏览器 Worker 中执行，JavaScript 用于界面和绘图。首次运行需要从 CDN 下载 Pyodide 314.0.7 和 NumPy / SymPy；输入文件与结果留在浏览器，不需要安装 Python 或启动计算服务器。这是独立移植，尚未覆盖全部上游接口。</p><h3>先从点群学起</h3><p><a href="#pointgroups" data-view="pointgroups">32 点群课堂</a>提供分步课程、完整晶体学点群图谱、对称操作实验和即时自测。讲解参考 Dresselhaus 等的《Group Theory》（2008），给出核对过的章节与页码；课堂表格由 Python 从现有群数据计算并验证，可将对应的 Γ 点例子送入工作台。</p><h3>继续学习空间群、自旋与磁群</h3><p><a href="#academy" data-view="academy">空间群 · 双群 · 磁群课堂</a>包括 15 个学习单元、30 道带解析练习，以及全部 230 空间群、1,651 磁空间群和 122 磁点群的教学索引。交互实验由浏览器内 Python 计算 Seitz 操作、旋量、磁矩和反铁磁组合对称；可将目录中的群送入单值或双值表示工作台。材料实例提供 NaCl、Si、GaAs、Fe、NiO 和 MnF₂ 的三维操作演示；分步推导页可逐步展开提示、公式和自测反馈。<a href="docs/materials-classroom.md" target="_blank">材料模型与来源</a> · <a href="docs/symmetry-course.md">课程来源与约定</a>。</p><h3>从一次计算开始</h3><ol><li>选择 SG、MSG 或 MPG，搜索群编号或国际符号。</li><li>输入 BC 原胞倒易基矢下的波矢，支持 <code>1/2</code> 等分数。</li><li>选择单值或双值表示，点击计算。</li><li>检查特征标、表示矩阵、群操作和数值验证，导出 JSON / CSV。</li></ol><h3>坐标与可视化</h3><p>操作 {R | t} 使用 BC 直接原胞的分数坐标。波矢使用对应倒易分数坐标，幺正操作作用为 R⁻ᵀk，反幺正操作为 −R⁻ᵀk。平移相位为 exp(−2πi k·t)。磁群使用 BNS family 的 BC 原胞。</p><p>右侧显示倒易原胞示意图，不是 Wigner–Seitz 布里渊区。晶格常数采用示意值，不能用于定量长度和角度比较。部分高对称点名称依赖 BZ 类型；按钮悬停可查看所属 BZ，实际计算始终按输入坐标进行。</p><h3>表示构造与验证</h3><p>在有限平移商群上构造含 Bloch 与自旋因子的正则表示，通过厄米对易算符分解不可约子空间。双值计算使用上游自旋旋转矩阵；反幺正共表示包含复共轭与自旋时间反演。</p><p>计算结果必须通过维数平方和、特征标正交性及表示乘法关系检查。JSON 保留验证误差。失败时显示错误，不以预置结果替代。</p><div class="notice warning">D₁、D₂… 和 C₁、C₂… 是当前计算的数值编号。普通空间群会另列匹配到的 BC / Bilbao 标签与证书；缺失或歧义标签保留为空。磁共表示仍用本地编号。数值基底和原文矩阵可存在相似变换，不应按矩阵元素逐项直接比较。</div></section>
 <section class="panel prose"><h2>当前功能覆盖</h2><table><thead><tr><th>功能</th><th>状态</th></tr></thead><tbody><tr><td>230 SG、1651 MSG、122 MPG 数据</td><td>已实现</td></tr><tr><td>BNS / OG 编号与符号检索</td><td>已实现</td></tr><tr><td>任意数值 k 点的小群与 k 星</td><td>已实现</td></tr><tr><td>单值 / 双值小群不可约表示</td><td>已实现 · 数值标签</td></tr><tr><td>磁小群 Wigner 类型与共表示</td><td>已实现 · 数值标签</td></tr><tr><td>SG / MSG 全 k 星诱导表示</td><td>已实现</td></tr><tr><td>SG / MSG 任意 k 星直积</td><td>已实现</td></tr><tr><td>trace / JSON 能带表示匹配</td><td>已实现 · BC 原胞输入</td></tr><tr><td>磁点群共表示直积</td><td>已实现</td></tr><tr><td>BC / Bilbao 标准标签映射</td><td>已实现 · 普通 SG，按标准表与完整特征标匹配</td></tr><tr><td>POSCAR / CIF → BC 晶胞</td><td>已实现 · 230 SG 设置，有序三维周期结构</td></tr></tbody></table><h3>晶胞与标准标签</h3><p><a href="#structure" data-view="structure">结构 → BC 晶胞</a>支持 POSCAR / CONTCAR、CIF 和 Python 晶胞数据。浏览器通过 spglib WebAssembly 识别空间群，沿用原项目全部 230 组 BC 设置；输出基矢、原点、波矢变换和 POSCAR / CIF。CIF 部分占位、无序和磁结构需先给出适用的有序结构模型。已有 DFT trace 还涉及平移相位与自旋框架，结构标准化不能自动代替 trace 转换。</p><p>普通 SG 表示按完整特征标匹配 BC 和 Bilbao 标准表，保留每个本地编号与匹配证书。BZ 类型、特殊参数点或标准库未覆盖处可能无法唯一命名。<a href="docs/standard-labels.md">标准标签来源与范围</a> · <a href="docs/structure-bc.md">结构转换方法</a>。</p><h3>MagneticTB · 模型与拓扑</h3><p>对称性约束跃迁、实 s/p/d 轨道、自旋和反幺正操作；支持能带、Wannier90 hr、有限边界、薄膜、表面 Green 函数、Wilson/Berry 与 Chern 数。晶格按行输入，H(k) 使用 exp(+2πi k·R) 周期轨道规范。拓扑量需要有带隙，并应核对网格收敛。</p><p>精确符号模块支持分圆域、精确跃迁约束、Bloch Hamiltonian、k·p 与多项式轨道。符号空间群工具可从群号和符号 k 线自动构造精确小表示、磁共表示及全 k 星诱导，重建精确自旋提升并逐项验证半线性乘法；符号接口还处理共核、交织和投影。输出使用本次计算的局部编号。<a href="docs/symbolic-spacegroups.md">查看符号算法与限制</a>；<a href="data/symbolic-api-coverage.json">查看逐项覆盖记录</a>。完整自旋空间群目录、DFT 拟合和 Z₂ 不变量仍未移植。</p><h3>CrystKit · 精确晶体群</h3><p>有理数仿射闭合、坐标与原点变换、平移格简化、有限商群生成元、点轨道、矩阵共轭、GL(n,ℤ) 元素有限阶和 230 个三维空间群参考匹配。未找到受限搜索匹配时不推断非同构。</p><p>新增 CARAT 1–6 维全部 8,329 个 Q 类代表与精确分类证书；固定整数点群的完整上同调、特定完整正规化子、扩张轨道和无限空间群生成证书。整数类工具新增有限导子区间算法：对已验证的极大序模型，有限遍历证明候选整数格已覆盖，再通过完整算术作用区分 Z 类。支持交换群、分裂有理表示及绝对不可约表示等情形；仿射类再求完整上同调与正规化子轨道。算术中心化子工具计算饱和整数序、中心分解和单位范数方程，并对已实现的分裂、实二次及定值范数分支给出完整单位群。一般数域、除代数或资源未穷尽的情况会明确报告未完成。新增无挠性和中心判定以精确 Smith 可解性检验全部点群陪集。商群最小生成元不等于无限空间群最小生成元。</p><p><a href="#" data-view="advanced">打开精确代数与高维群 →</a>。Q 等价、Z 等价和仿射等价有不同约束；界面保留完整性状态和精确证书。符号秩的例外参数条件必须一并使用，未找到受限搜索结果不能作为不存在的证明。</p><h3>可复现与开放源码</h3><p>程序、数据与数值算法随静态网站提供。<a href="source.zip" download>下载网站完整源代码</a>。该版本遵循 <a href="licenses/MSGCorep-GPL-3.0.txt">GPL-3.0</a>；四个项目及 CARAT 的作者声明与许可证均保留。<a href="data/python-provenance.json">Python 移植来源与覆盖记录</a>。<a href="python/cli.py" download>下载 Python 命令行入口</a>。</p><h3>如何解释结果</h3><p>普通小群表示列出幺正操作的特征标。磁共表示的反幺正矩阵必须与 K 一起使用，不能当作普通线性表示。能带匹配由幺正特征标确定共表示分解，磁小群匹配使用共表示限制的归一化范数；磁共表示的上游标准标签仍需参考原 MSGCorep。</p></section>
 <section class="panel prose full-span"><h2>项目来源与文献</h2><div class="workspace-grid"><div><h3>SpaceGroupIrep</h3><p><a target="_blank" rel="noreferrer" href="https://github.com/goodluck1982/SpaceGroupIrep">goodluck1982 / SpaceGroupIrep ↗</a><br>空间群生成元、BC 原胞旋转、k 点表及表示元数据。<br><a href="https://doi.org/10.1016/j.cpc.2021.107993" target="_blank" rel="noreferrer">Computer Physics Communications 265, 107993 (2021)</a></p></div><div><h3>MSGCorep</h3><p><a target="_blank" rel="noreferrer" href="https://github.com/goodluck1982/MSGCorep">goodluck1982 / MSGCorep ↗</a><br>磁群编号、磁群操作、自旋矩阵及磁点群数据。<br><a href="https://doi.org/10.1016/j.cpc.2023.108722" target="_blank" rel="noreferrer">Computer Physics Communications 288, 108722 (2023)</a></p></div></div><div class="workspace-grid"><div><h3>MagneticTB</h3><p><a href="https://github.com/zhangzeyingvv/MagneticTB" target="_blank" rel="noreferrer">zhangzeyingvv / MagneticTB ↗</a><br>对称性约束紧束缚模型工作流；本站采用 NumPy 数值和 SymPy 精确实现。<a href="licenses/MagneticTB-LICENSE.txt">GPL-3.0 许可</a>。</p></div><div><h3>CrystKit</h3><p><a href="https://github.com/hongyi-zhao/CrystKit" target="_blank" rel="noreferrer">hongyi-zhao / CrystKit ↗</a><br>精确仿射群与矩阵群算法；本站采用 Fraction / SymPy 实现。<a href="licenses/CrystKit-LICENSE.txt">GPL-2.0-or-later 许可</a>，组合版本采用 GPL-3.0。</p></div></div><h3>CARAT · 高维有理类</h3><p><a href="https://github.com/lbfm-rwth/carat" target="_blank" rel="noreferrer">lbfm-rwth / carat ↗</a> · <a href="data/carat/manifest.json">完整目录与来源哈希</a> · <a href="licenses/CARAT-LICENSE.txt">GPL-2.0-or-later 许可</a>。</p><p>使用这些数据发表研究时，请引用原始软件和论文。本网站为独立浏览器实现，不代表原项目作者发布或背书。</p></section></div>`;}

document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){e.preventDefault();setView(nav.dataset.view);}if(!e.target.closest('.search-wrap'))$('#group-options')?.classList.add('hidden');});$('#help-button').onclick=()=>setView('docs');$('#export-top').onclick=()=>{if(state.view==='academy'){const result=getSymmetryCourseResult();if(result)download(JSON.stringify(result,null,2),'symmetry-course.json');else toast('请先载入课程或运行交互实验。');}else if(state.view==='pointgroups'){const result=getPointgroupResult();if(result)download(JSON.stringify(result,null,2),'pointgroup-learning.json');else toast('请等待教学数据加载完成。');}else if(state.view==='structure'){const result=getStructureResult();if(result)download(JSON.stringify(result,null,2),'bc-structure.json');else toast('请先完成晶胞转换。');}else if(state.view==='advanced'){const result=getAdvancedResult();if(result)download(JSON.stringify(result,null,2),'exact-result.json');else toast('请先运行当前工具的计算。');}else if(['magnetictb','crystkit'].includes(state.view)){const result=getResearchResult(state.view);if(result)download(JSON.stringify(result,null,2),state.view+'-result.json');else toast('请先运行当前工具的计算。');}else if(state.view==='products'){const button=$('#export-product');if(button)button.click();else toast('请先完成当前直积分解。');}else if(state.view==='bands'){const button=$('#export-bands');if(button)button.click();else toast('请先完成当前能带匹配。');}else exportJSON();};
$('#cancel-python').onclick=cancelPython;
onPythonStatus(({status,message})=>{$('#data-status').textContent=message;$('#cancel-python').classList.toggle('hidden',!['loading','running'].includes(status));});
try{const [sg,msg,mpg]=await Promise.all(['space-groups','magnetic-groups','points'].map(async name=>{const r=await fetch(`data/${name}.json`);if(!r.ok)throw new Error(`${name} 数据加载失败`);return r.json();}));databases={sg,msg,mpg};state.group=sg.groups.find(g=>g.number===225);$('#data-status').textContent='数据库就绪 · Python 按需加载';const initialView=location.hash.slice(1);if(Object.hasOwn(labels,initialView))setView(initialView);else render();if(state.view==='workbench')await calculate();}catch(e){$('#app').innerHTML=`<div class="notice error">${esc(e.message)}。请刷新页面重试，或通过 HTTP 静态服务器打开网站。</div>`;$('#data-status').textContent='加载失败';}
